# --- Positive: emergent flag (D-3) -----------------------------------------------------


def test_emergent_redeems_full_current_subscription_regardless_of_requested_multiplier(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("7"))
    make_portfolio(session, client)

    svc = OnboardingService(session)
    req = SubmitRedemptionReq(
        client_id=client.id, model_id=model.id, multiplier=Decimal("1"), emergent=True
    )
    dto = svc.submit_redemption(req)

    allotment = svc.repo.get_allotment(dto.id)
    assert allotment.multiplier == Decimal("7")
    assert allotment.emergent is True


def test_emergent_forces_expected_cash_out_to_t_plus_1_regardless_of_requested_date(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("7"))
    make_portfolio(session, client)

    svc = OnboardingService(session)
    far_future = date.today() + timedelta(days=90)
    req = SubmitRedemptionReq(
        client_id=client.id,
        model_id=model.id,
        multiplier=Decimal("1"),
        expected_cash_out=far_future,
        emergent=True,
    )
    dto = svc.submit_redemption(req)

    allotment = svc.repo.get_allotment(dto.id)
    expected = date.today() + timedelta(days=1)
    assert allotment.expected_cash_out.date() == expected


def test_emergent_does_not_bypass_either_approval_gate(session):
    """D-3: no bypass -- an emergent redemption above $300k still lands in
    awaiting_co, not some emergent-only fast lane."""
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("500000"))
    make_portfolio(session, client)

    svc = OnboardingService(session)
    req = SubmitRedemptionReq(
        client_id=client.id, model_id=model.id, multiplier=Decimal("1"), emergent=True
    )
    dto = svc.submit_redemption(req)
    assert dto.status == "awaiting_co"  # full sub (500000) * 1 > 300000


