# --- Invariants: no subscription/portfolio write on submit -----------------------------


@pytest.mark.parametrize("emergent", [False, True])
@pytest.mark.parametrize("multiplier", [Decimal("300000"), Decimal("300001")])
def test_submit_never_touches_subscription_or_portfolio(session, multiplier, emergent):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("500000"))
    make_portfolio(
        session,
        client,
        cash_deposit=Decimal("123"),
        amount_in_trade=Decimal("456"),
        previous_amount_in_trade=Decimal("789"),
    )
    session.expire_all()

    svc = OnboardingService(session)
    req = SubmitRedemptionReq(
        client_id=client.id, model_id=model.id, multiplier=multiplier, emergent=emergent
    )
    svc.submit_redemption(req)

    sub = session.get(ClientSubscription, (client.id, model.id))
    assert sub.multiplier == Decimal("500000")
    portfolio = session.get(ClientPortfolio, client.id)
    assert portfolio.cash_deposit == Decimal("123")
    assert portfolio.amount_in_trade == Decimal("456")
    assert portfolio.previous_amount_in_trade == Decimal("789")


def test_submit_inserts_exactly_one_allotment_row_and_one_event(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("5"))
    make_portfolio(session, client)

    svc = OnboardingService(session)
    req = SubmitRedemptionReq(client_id=client.id, model_id=model.id, multiplier=Decimal("2"))
    dto = svc.submit_redemption(req)

    allotment = svc.repo.get_allotment(dto.id)
    assert allotment.kind == AllotRdmpKind.REDEMPTION
    assert allotment.status in (AllotRdmpStatus.AWAITING_PC, AllotRdmpStatus.AWAITING_CO)

    from app.models.onboarding import ClientEvent

    events = session.query(ClientEvent).filter(ClientEvent.user_id == client.id).all()
    assert len(events) == 1


